<?php
/** Mobile-first event cards; every link is generated by the MVC Request helper. */
declare(strict_types=1);
use Vereinssystem\Core\View;
?>
<section class="vs-section vs-section--first">
    <div class="vs-toolbar">
        <div><p class="vs-kicker">Vereinsleben</p><h1>Veranstaltungen</h1>
            <p class="vs-muted">Termine mit frei planbaren Aufgaben und Mitgliedern.</p></div>
        <?php if ($canCreate): ?><a class="vs-button vs-button--primary" href="<?= View::escape($createUrl) ?>">+ Veranstaltung</a><?php endif; ?>
    </div>
    <?php if ($isAdmin): ?>
        <p><a class="vs-button" href="<?= View::escape($inactive ? $listUrl : $listUrl.'&inactive=1') ?>">
            <?= $inactive ? 'Nur aktive Veranstaltungen' : 'Inaktive mit anzeigen' ?></a></p>
    <?php endif; ?>
    <?php if ($flash): ?><div class="vs-alert" role="status"><?= View::escape($flash) ?></div><?php endif; ?>
    <div class="vs-directory-grid">
        <?php foreach ($events as $event): ?>
            <article class="vs-card vs-directory-card">
                <p class="vs-kicker"><?= View::escape(date('d.m.Y · H:i', (int)$event['startzeit'])) ?></p>
                <h2><?= View::escape($event['veranstaltungsname']) ?></h2>
                <p class="vs-muted"><?= View::escape($event['ortsname'] ?: 'Kein Ort hinterlegt') ?></p>
                <p><?= (int)$event['task_count'] ?> geplante Aufgaben</p>
                <?php if ((int)$event['status'] !== 1): ?><p class="vs-muted">Inaktiv</p><?php endif; ?>
                <a class="vs-button" href="<?= View::escape($viewUrl.'&id='.(int)$event['veranstaltungs_id']) ?>">Aufgaben ansehen</a>
            </article>
        <?php endforeach; ?>
    </div>
    <?php if (!$events): ?><div class="vs-card vs-empty">Noch keine Veranstaltungen angelegt.</div><?php endif; ?>
</section>
